#!/usr/bin/env node
/* oxlint-disable t3code/namespace-node-imports -- same style as the other scripts here */
// Writes packages/tessaya-shared/src/docsBundle.data.ts from docs/user's Help pages, so every build carries them:
// `node scripts/tessaya/docs-bundle.mjs`. docs.test.ts fails while the bundle and the pages differ.
import { readFileSync, writeFileSync } from "node:fs";

const root = new URL("../../", import.meta.url);
const read = (name) => readFileSync(new URL(`docs/user/${name}`, root), "utf8");

export const bundleText = (features, lessons) =>
  `// Generated by scripts/tessaya/docs-bundle.mjs from docs/user; edit those pages, then run it.\n` +
  `export const DOCS_FEATURES_MD = ${JSON.stringify(features)};\n` +
  `export const DOCS_LESSONS_MD = ${JSON.stringify(lessons)};\n`;

if (import.meta.url === `file://${process.argv[1]}`)
  writeFileSync(
    new URL("packages/tessaya-shared/src/docsBundle.data.ts", root),
    bundleText(read("tessaya-features.md"), read("tessaya-lessons.md")),
  );
